   408  idn2_lookup_u8 (const uint8_t * src, uint8_t ** lookupname, int flags)
   409  {
   410    size_t lookupnamelen = 0;
   411    uint8_t _lookupname[IDN2_DOMAIN_MAX_LENGTH + 1];
   412    uint8_t _mapped[IDN2_DOMAIN_MAX_LENGTH + 1];
   413    int rc;
   414
   415    if (src == NULL)
   416      {
   417        if (lookupname)
   418          *lookupname = NULL;
   419        return IDN2_OK;
   420      }
   421
   422    rc = set_default_flags(&flags);
   423    if (rc != IDN2_OK)
   424      return rc;
   425
   426    if (!(flags & IDN2_NO_TR46))
   427      {
   428        uint8_t *out;
   429        size_t outlen;
   430
   431        rc = _tr46 (src, &out, flags);
   432        if (rc != IDN2_OK)
   433          return rc;
   434
   435        outlen = u8_strlen (out);
   436        if (outlen >= sizeof (_mapped))
   437          {
   438            free (out);
   439            return IDN2_TOO_BIG_DOMAIN;
   440          }
   441
   442        memcpy (_mapped, out, outlen + 1);
   443        src = _mapped;
   444        free (out);
   445      }
   446
   447    do
   448      {
   449        const uint8_t *end = (uint8_t *) strchrnul ((const char *) src, '.');
   450        /* XXX Do we care about non-U+002E dots such as U+3002, U+FF0E
   451           and U+FF61 here?  Perhaps when IDN2_NFC_INPUT? */
   452        size_t labellen = end - src;
   453        uint8_t tmp[IDN2_LABEL_MAX_LENGTH];
   454        size_t tmplen = IDN2_LABEL_MAX_LENGTH;
   455
   456        rc = label (src, labellen, tmp, &tmplen, flags);
   457        if (rc != IDN2_OK)
   458          return rc;
   459
   460        if (lookupnamelen + tmplen
   461            > IDN2_DOMAIN_MAX_LENGTH - (tmplen == 0 && *end == '\0' ? 1 : 2))
   462          return IDN2_TOO_BIG_DOMAIN;
   463
   464        memcpy (_lookupname + lookupnamelen, tmp, tmplen);
   465        lookupnamelen += tmplen;
   466
   467        if (*end == '.')
   468          {
   469            if (lookupnamelen + 1 > IDN2_DOMAIN_MAX_LENGTH)
   470              return IDN2_TOO_BIG_DOMAIN;
   471
   472            _lookupname[lookupnamelen] = '.';
   473            lookupnamelen++;
   474          }
   475        _lookupname[lookupnamelen] = '\0';
   476
   477        src = end;
   478      }
   479    while (*src++);
   480
   481    if (lookupname)
   482      {
   483        uint8_t *tmp = (uint8_t *) malloc (lookupnamelen + 1);
   484
   485        if (tmp == NULL)
   486          return IDN2_MALLOC;
   487
   488        memcpy (tmp, _lookupname, lookupnamelen + 1);
   489        *lookupname = tmp;
   490      }
   491
   492    return IDN2_OK;
   493  }
